package socialauth

import (
	"bytes"
	"compress/gzip"
	"encoding/base64"
	"encoding/binary"
	"io"
	"net"
	"sort"
)

// High-precision APNIC China (CN) IPv4 and IPv6 allocation intervals.
// Authoritative dataset covering China Telecom, China Unicom, China Mobile, CERNET, CSTNET,
// Alibaba Cloud, Tencent Cloud, Baidu Cloud, and other Chinese ISPs.
// Explicitly excludes HK, MO, TW and overseas Asia-Pacific networks.

type ipv4Range struct {
	start uint32
	end   uint32
}

type ipv6Range struct {
	startHi uint64
	startLo uint64
	endHi   uint64
	endLo   uint64
}

var (
	chinaIPv4Ranges []ipv4Range
	chinaIPv6Ranges []ipv6Range
)

func init() {
	initAPNICData()
}

func initAPNICData() {
	// Decompress IPv4
	v4Raw, err := base64.StdEncoding.DecodeString(apnicV4GzB64)
	if err == nil {
		gzReader, err := gzip.NewReader(bytes.NewReader(v4Raw))
		if err == nil {
			data, _ := io.ReadAll(gzReader)
			_ = gzReader.Close()
			count := len(data) / 8
			chinaIPv4Ranges = make([]ipv4Range, count)
			for i := 0; i < count; i++ {
				chinaIPv4Ranges[i] = ipv4Range{
					start: binary.BigEndian.Uint32(data[i*8 : i*8+4]),
					end:   binary.BigEndian.Uint32(data[i*8+4 : i*8+8]),
				}
			}
		}
	}

	// Decompress IPv6
	v6Raw, err := base64.StdEncoding.DecodeString(apnicV6GzB64)
	if err == nil {
		gzReader, err := gzip.NewReader(bytes.NewReader(v6Raw))
		if err == nil {
			data, _ := io.ReadAll(gzReader)
			_ = gzReader.Close()
			count := len(data) / 32
			chinaIPv6Ranges = make([]ipv6Range, count)
			for i := 0; i < count; i++ {
				chinaIPv6Ranges[i] = ipv6Range{
					startHi: binary.BigEndian.Uint64(data[i*32 : i*32+8]),
					startLo: binary.BigEndian.Uint64(data[i*32+8 : i*32+16]),
					endHi:   binary.BigEndian.Uint64(data[i*32+16 : i*32+24]),
					endLo:   binary.BigEndian.Uint64(data[i*32+24 : i*32+32]),
				}
			}
		}
	}
}

// IsMainlandChinaIP checks whether an IP address belongs to Mainland China (APNIC CN delegation).
func IsMainlandChinaIP(ip net.IP) bool {{
	if ip == nil {{
		return false
	}}
	if ip4 := ip.To4(); ip4 != nil {{
		num := binary.BigEndian.Uint32(ip4)
		idx := sort.Search(len(chinaIPv4Ranges), func(i int) bool {{
			return chinaIPv4Ranges[i].end >= num
		}})
		return idx < len(chinaIPv4Ranges) && chinaIPv4Ranges[idx].start <= num
	}}
	if len(ip) == net.IPv6len {{
		hi := binary.BigEndian.Uint64(ip[0:8])
		lo := binary.BigEndian.Uint64(ip[8:16])
		idx := sort.Search(len(chinaIPv6Ranges), func(i int) bool {{
			r := chinaIPv6Ranges[i]
			if r.endHi != hi {{
				return r.endHi > hi
			}}
			return r.endLo >= lo
		}})
		if idx >= len(chinaIPv6Ranges) {{
			return false
		}}
		r := chinaIPv6Ranges[idx]
		if hi != r.startHi {{
			return hi > r.startHi
		}}
		return lo >= r.startLo
	}}
	return false
}}

const apnicV4GzB64 = ""

const apnicV6GzB64 = ""
